// GENERATED by docs/api/build-openapi-ts.mjs from docs/api/openapi.yaml — do not edit by hand.
export const OPENAPI_YAML = "openapi: 3.1.0\ninfo:\n  title: Covva API\n  version: 1.0.0\n  summary: REST API for the Covva mobile app and partner (broker/insurer) integrations.\n  description: |\n    Covva is a **technology platform**. It is not an insurer or broker, does not\n    give advice in its own name and never holds premiums. Every response that concerns a\n    transaction carries the information needed to show the mandatory disclosure.\n\n    ## Authentication\n    * **Customer / partner users** — `Authorization: Bearer <Supabase access token>` (mobile) or the\n      Supabase session cookie (web). Requests run as that user, so Postgres Row Level Security applies.\n    * **Partner integrations** — `x-api-key: imk_<prefix>_<secret>` (see `/partner/*`). Keys belong to a\n      broker or insurer organisation and carry scopes: `requests:read`, `quotes:write`,\n      `policies:issue`, `claims:write`, `policies:read`, `claims:read`, `finance:read` (or `*`).\n\n    ## Envelope\n    Every JSON response (except the AI chat stream and redirects) is an `ApiResult`:\n    `{ \"ok\": true, \"data\": … }` or `{ \"ok\": false, \"error\": { \"code\", \"message\", \"details?\" } }`.\n\n    | HTTP | `error.code` | Meaning |\n    |---|---|---|\n    | 400 | `invalid_input` | Validation failed (`details` lists `{ path, message }`) |\n    | 401 | `unauthorised` | Missing/expired token or invalid API key |\n    | 403 | `forbidden` | Authenticated but not allowed |\n    | 404 | `not_found` | Not found or not visible to you |\n    | 409 | `conflict` | Duplicate / already done |\n    | 422 | `business_rule` | A product rule blocked it (e.g. quote expired, broker not disclosed). Show `message` to the user. |\n    | 429 | `rate_limited` | Slow down; see `Retry-After` |\n    | 503 | `unavailable` | Feature switched off or not configured (AI, payments) |\n    | 500 | `internal_error` | Unexpected error; quote `x-request-id` to support |\n\n    Every response has an `x-request-id` header (send your own to correlate).\n\n    ## Client identification and platform access (Addendum 4)\n    Send `X-Covva-Client: mobile | web | partner-web` on every call (missing = `web`). Customers and\n    brokers use the mobile app; **insurer** (and staff) accounts are web-only: a call from `mobile` by an\n    account whose only memberships are insurer/staff gets `403 forbidden` with\n    `details.reason = \"insurer_web_only\"` and `details.portalUrl` — show the message and link to the web portal.\n    Dual-role users pick a workspace with `POST /me/workspace`; `GET /me` lists `workspaces` with `mobileAllowed`.\n\n    ## Product rules clients must honour\n    * Show the broker-of-record disclosure and record it (`POST /requests/{id}/disclosure`) **before** an application.\n    * Only `ready_to_accept` quotes can be applied for, and only before `valid_until`.\n    * Payment confirmation never activates cover. Show cover as active only when `policy.status = active`.\n    * Reporting a claim is not approval. Only the insurer decides claims.\n    * When `demoMode` is true, show \"Illustrative only · Demo data\" near insurer names and prices.\n    * AI output is labelled as AI-assisted and is never a suitability or claim decision.\n  contact:\n    name: Platform engineering\n    email: support@covva.com.gh\nservers:\n  - url: https://{host}/api/v1\n    variables:\n      host:\n        default: covva.com.gh\n  - url: http://localhost:3000/api/v1\nsecurity:\n  - bearerAuth: []\ntags:\n  - name: Webhooks\n    description: |\n      Signed HTTP callbacks to partner endpoints (configured in Team settings → Developer). Every delivery is a\n      `POST` with headers `x-covva-event`, `x-covva-delivery`, `x-covva-timestamp` and `x-covva-signature`\n      (`HMAC-SHA256(endpoint secret, \"{timestamp}.{raw body}\")`, hex). Respond 2xx within 10 s; failures retry after\n      1 min, 5 min, 30 min, 2 h and 12 h. Payloads carry ids, references, statuses, amounts and dates only — never\n      personal data; fetch details through the API. See `docs/WEBHOOKS.md`.\n  - name: Me\n  - name: Catalogue\n  - name: Lookups\n  - name: Requests\n  - name: Documents\n  - name: Applications & payments\n  - name: Policies\n  - name: Verification\n  - name: Claims\n  - name: Complaints\n  - name: Notifications & devices\n  - name: AI\n  - name: Partner API\n  - name: System\n\npaths:\n  /me:\n    get:\n      tags: [Me]\n      summary: Current user — profile, memberships, workspaces, feature flags, consent state\n      parameters: [{ $ref: \"#/components/parameters/CovvaClient\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Me\" }\n        \"401\": { $ref: \"#/components/responses/Error\" }\n        \"403\":\n          description: Insurer/staff account calling from the mobile app (`details.reason = insurer_web_only`)\n          content: { application/json: { schema: { $ref: \"#/components/schemas/ErrorEnvelope\" } } }\n    patch:\n      tags: [Me]\n      summary: Update own profile\n      description: KYC status can't be changed by the client (enforced in the database).\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/UpdateProfileInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /me/workspace:\n    post:\n      tags: [Me]\n      summary: Choose the active workspace (dual-role users)\n      description: |\n        Persists `profiles.active_workspace`. The workspace must be one of the caller's `workspaces` and usable from the\n        calling client — an insurer workspace cannot be activated with `X-Covva-Client: mobile`.\n      parameters: [{ $ref: \"#/components/parameters/CovvaClient\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/SetActiveWorkspaceInput\" } } }\n      responses:\n        \"200\":\n          description: Stored choice\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties:\n                      data:\n                        type: object\n                        properties:\n                          activeWorkspace: { $ref: \"#/components/schemas/ActiveWorkspace\" }\n                          workspace: { $ref: \"#/components/schemas/Workspace\" }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /me/consents:\n    post:\n      tags: [Me]\n      summary: Record consent decisions (append-only)\n      description: When `version` is omitted the current `terms_version` / `privacy_version` is used.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/RecordConsentsInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /catalog/categories:\n    get:\n      tags: [Catalogue]\n      summary: Insurance categories with availability and `risk_schema` (form definition)\n      security: []\n      responses:\n        \"200\":\n          description: Categories\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { type: array, items: { $ref: \"#/components/schemas/Category\" } } }\n  /catalog/categories/{slug}:\n    get:\n      tags: [Catalogue]\n      summary: One category with approved products from participating insurers\n      security: []\n      parameters: [{ name: slug, in: path, required: true, schema: { type: string } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /catalog/insurers:\n    get:\n      tags: [Catalogue]\n      summary: Public directory of active insurers and brokers (for \"add a policy bought elsewhere\")\n      security: []\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /lookups/vehicle:\n    post:\n      tags: [Lookups]\n      summary: Prefill a motor quote from a Ghana registration number\n      description: |\n        Normalises the plate (`GR 1234-23`) and looks it up in the cache, then the configured provider\n        (DVLA / partner API when `DVLA_API_URL` is set). `found: false` just means \"ask the customer\" —\n        quoting never depends on it. Returns vehicle facts only (make, model, year, body, colour,\n        engine, seats, use), never the keeper. Rate-limited (write bucket).\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/VehicleLookupInput\" } } }\n      responses:\n        \"200\":\n          description: Lookup result\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/VehicleLookupResult\" } }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n  /needs-assessment:\n    get:\n      tags: [Catalogue]\n      summary: The \"help me choose\" questions\n      security: []\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Catalogue]\n      summary: Run the needs assessment and store the answers\n      description: Works signed-in (bearer) or anonymously (pass `anonymousId`). Returns categories to consider — not product advice.\n      security: [{}, { bearerAuth: [] }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/NeedsAssessmentInput\" } } }\n      responses:\n        \"200\":\n          description: Suggestions\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/NeedsResult\" } }\n\n  /requests:\n    get:\n      tags: [Requests]\n      summary: The customer's requests\n      parameters:\n        - { $ref: \"#/components/parameters/Limit\" }\n        - { $ref: \"#/components/parameters/Before\" }\n        - { name: status, in: query, schema: { $ref: \"#/components/schemas/RequestStatus\" } }\n        - { name: open, in: query, schema: { type: string, enum: [\"true\", \"false\"] } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n    post:\n      tags: [Requests]\n      summary: Create (and by default submit) a request\n      description: |\n        Validates `risk` against the category's `risk_schema`, routes exactly one broker of record,\n        prices estimates from approved rating rules and creates document tasks. `source` is recorded as `mobile`.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/CreateRequestInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /requests/{id}:\n    get:\n      tags: [Requests]\n      summary: Request detail — customer-visible timeline, tasks, broker, documents, applications, payments, policies\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /requests/{id}/cancel:\n    post:\n      tags: [Requests]\n      summary: Cancel an open request (customer)\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        content: { application/json: { schema: { type: object, properties: { reason: { type: string, maxLength: 500 } } } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /requests/{id}/quotes:\n    get:\n      tags: [Requests]\n      summary: Quotes, comparison result and disclosure text\n      description: |\n        `comparison` is the engine output (`insurersCompared`, `productsCompared`, `criteria`, `ranked`, `paidPlacements`,\n        `materialExclusions`, `disclaimer`). Show `summary` (e.g. \"3 quotes from 3 participating insurers compared\"),\n        each quote's `statusLabel`, `labels` (explained, never an unexplained \"best\"), `valid_until` and `comparedAt`.\n        Paid placements are listed separately and never ranked.\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\":\n          description: Quotes\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/QuotesResult\" } }\n  /requests/{id}/disclosure:\n    post:\n      tags: [Requests]\n      summary: Acknowledge the broker-of-record disclosure (required before applying). Idempotent.\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        content: { application/json: { schema: { $ref: \"#/components/schemas/DisclosureAckInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /requests/{id}/share:\n    post:\n      tags: [Requests]\n      summary: Save & share the comparison (link, WhatsApp or email)\n      description: |\n        Creates a share token valid for 14 days. `url` opens a public, read-only comparison\n        (`/q/{token}`) that shows quote summaries only — never the customer's name, reference or risk\n        details beyond the cover title. `whatsappUrl` is a `https://wa.me/?text=` link with `text`\n        prefilled; `channel: email` also emails the summary to `email` (defaults to the account email).\n        \"Resume later\" needs nothing extra: the request itself is saved — `GET /requests`.\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ShareQuotesInput\" } } }\n      responses:\n        \"201\":\n          description: Share created\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/ShareResult\" } }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /requests/{id}/messages:\n    get:\n      tags: [Requests]\n      summary: Message thread with the broker (oldest first within the page)\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { $ref: \"#/components/parameters/Limit\" }, { $ref: \"#/components/parameters/Before\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n    post:\n      tags: [Requests]\n      summary: Send a message on the thread\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/PostMessageInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n  /requests/{id}/tasks/{taskId}/complete:\n    post:\n      tags: [Requests]\n      summary: Complete a customer task (document tasks need `documentId`)\n      parameters:\n        - { $ref: \"#/components/parameters/Id\" }\n        - { name: taskId, in: path, required: true, schema: { type: string, format: uuid } }\n      requestBody:\n        content: { application/json: { schema: { $ref: \"#/components/schemas/CompleteTaskInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n\n  /documents/upload-url:\n    post:\n      tags: [Documents]\n      summary: Get a signed upload URL in the private documents bucket\n      description: |\n        Path layout `{customerId}/{scope}/{uuid}-{fileName}`. Then `PUT` the file bytes to `signedUrl`\n        with the returned headers, then confirm with `POST /documents` (body provided in `confirm.body`).\n        Uploading is not the same as notifying the insurer — the broker delivers documents.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/UploadUrlInput\" } } }\n      responses:\n        \"200\":\n          description: Upload target\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties:\n                      data:\n                        type: object\n                        properties:\n                          bucket: { type: string }\n                          path: { type: string }\n                          token: { type: string }\n                          signedUrl: { type: string, format: uri }\n                          method: { type: string, enum: [PUT] }\n                          headers: { type: object, additionalProperties: { type: string } }\n                          expiresInSeconds: { type: integer }\n                          confirm: { type: object }\n  /documents:\n    post:\n      tags: [Documents]\n      summary: Confirm an upload and create the document record\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ConfirmUploadInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n  /documents/{id}/url:\n    get:\n      tags: [Documents]\n      summary: Signed download URL (valid 5 minutes)\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { name: download, in: query, schema: { type: string, enum: [\"true\", \"false\"] } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /applications:\n    post:\n      tags: [Applications & payments]\n      summary: Apply for a ready-to-accept quote\n      description: Requires the broker disclosure to have been acknowledged and the quote to be `ready_to_accept` and unexpired. Idempotent per quote.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ApplyInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /payments:\n    post:\n      tags: [Applications & payments]\n      summary: Start payment for a submitted application\n      description: |\n        Revalidates the quote at checkout. Premiums settle to the insurer (Paystack subaccount, the insurer's\n        Hubtel merchant account, or the insurer's bank account) — never to Covva.\n        Open `authorizationUrl` in an in-app browser; for a direct MoMo prompt (`momo` given) `authorizationUrl`\n        is null — show `displayText` and poll `GET /payments/{id}`. Pass `callbackUrl` =\n        `https://<host>/api/payments/return` from the app to be redirected to `covva://payments/return`.\n        **Bank transfer** (`channel: bank_transfer`): `authorizationUrl` is null and `bankTransfer` holds the\n        account, amount and the reference to quote; the payment stays `pending` until the credit is confirmed\n        (automatically for a dedicated virtual account, otherwise by the insurer/admin reconciliation) — keep\n        polling or wait for the `payment.succeeded` notification. `provider` says which rail took the payment\n        (`paystack`, `hubtel`, `bank_transfer`, `simulator`).\n        In test environments without provider keys a **sandbox simulator** page is returned instead.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/InitPaymentRequest\" } } }\n      responses:\n        \"201\":\n          description: Payment started\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/InitiatePaymentResult\" } }\n        \"409\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n        \"503\": { $ref: \"#/components/responses/Error\" }\n  /payments/{id}:\n    get:\n      tags: [Applications & payments]\n      summary: Poll a payment (re-verifies pending Paystack payments)\n      description: \"`coverActive` is true only when the insurer has issued the policy.\"\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /policies:\n    get:\n      tags: [Policies]\n      summary: Policy wallet\n      parameters: [{ name: status, in: query, schema: { $ref: \"#/components/schemas/PolicyStatus\" } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /policies/{id}:\n    get:\n      tags: [Policies]\n      summary: Policy detail with cover wording, documents, claims and disclosure\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    patch:\n      tags: [Policies]\n      summary: Rename a policy (nickname only)\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { type: object, required: [nickname], properties: { nickname: { type: [string, \"null\"], maxLength: 60 } } } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /policies/{id}/documents:\n    get:\n      tags: [Policies]\n      summary: Policy documents with short-lived signed URLs\n      description: |\n        Every document on the policy with a 15-minute signed download URL. Documents generated by the platform on\n        the insurer's behalf (schedule, certificate, motor sticker, premium receipt) are flagged `generated: true`\n        and carry their `sha256`; each embeds a QR code that opens `verifyUrl`. `verificationCode` is the\n        10-character code behind that QR (null for policies bought elsewhere).\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\":\n          description: Documents\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties:\n                      data:\n                        type: object\n                        properties:\n                          policyId: { type: string, format: uuid }\n                          policyNumber: { type: [string, \"null\"] }\n                          verificationCode: { type: [string, \"null\"] }\n                          stickerNumber: { type: [string, \"null\"] }\n                          verifyUrl: { type: [string, \"null\"], format: uri }\n                          documents:\n                            type: array\n                            items:\n                              type: object\n                              properties:\n                                id: { type: string, format: uuid }\n                                kind: { type: string, description: \"policy_schedule | certificate | sticker | receipt | policy_wording | endorsement | other\" }\n                                fileName: { type: string }\n                                mimeType: { type: [string, \"null\"] }\n                                sizeBytes: { type: [integer, \"null\"] }\n                                sha256: { type: [string, \"null\"] }\n                                generated: { type: boolean }\n                                uploadedByParty: { type: string }\n                                createdAt: { type: string, format: date-time }\n                                url: { type: [string, \"null\"], format: uri, description: \"Signed URL, valid for expiresInSeconds\" }\n                                expiresInSeconds: { type: integer }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /policies/external:\n    post:\n      tags: [Policies]\n      summary: Add a policy bought elsewhere (shown as \"Added by you\")\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/AddExternalPolicyInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n  /policies/{id}/renewal:\n    post:\n      tags: [Policies]\n      summary: One-tap renewal — refreshed quotes for the same risk (or a switch review for external policies)\n      description: |\n        Creates a renewal request for the policy's risk with the policy's broker kept as broker of record and\n        estimates refreshed from current rates. `renewal` holds `sameInsurer` (the \"Renew with <insurer>\" offer:\n        `oneTap` is true when it is binding — apply and pay in one step), `alternatives` (cheapest first),\n        `savings` and `insurersCompared` (show \"1 insurer compared\" honestly). Existing cover is never\n        cancelled. Renewal prices are estimates until the insurer confirms.\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        content: { application/json: { schema: { $ref: \"#/components/schemas/RenewalInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"409\": { $ref: \"#/components/responses/Error\" }\n\n  /claims:\n    get:\n      tags: [Claims]\n      summary: The customer's claims\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Claims]\n      summary: Report a claim to the broker\n      description: \"Reporting is not approval: show `disclaimer`. Returns the evidence checklist (`requiredEvidence`).\"\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ReportClaimInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /claims/{id}:\n    get:\n      tags: [Claims]\n      summary: Claim detail, timeline and documents\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /claims/{id}/withdraw:\n    post:\n      tags: [Claims]\n      summary: Withdraw a claim before the insurer decides\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        content: { application/json: { schema: { type: object, properties: { reason: { type: string, maxLength: 500 } } } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /complaints:\n    get:\n      tags: [Complaints]\n      summary: The customer's complaints\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Complaints]\n      summary: File a complaint (routed to the broker, insurer or platform; SLA from settings)\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/FileComplaintInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n\n  /notifications:\n    get:\n      tags: [Notifications & devices]\n      summary: In-app notifications (with `deepLink` for the app) and unread count\n      parameters: [{ $ref: \"#/components/parameters/Limit\" }, { $ref: \"#/components/parameters/Before\" }, { name: unread, in: query, schema: { type: string, enum: [\"true\", \"false\"] } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n  /notifications/read:\n    post:\n      tags: [Notifications & devices]\n      summary: Mark notifications read\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema: { type: object, properties: { ids: { type: array, items: { type: string, format: uuid }, maxItems: 200 }, all: { type: boolean } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /devices:\n    post:\n      tags: [Notifications & devices]\n      summary: Register an Expo push token (moves the token to this user if it existed)\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/RegisterDeviceInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n  /devices/{token}:\n    delete:\n      tags: [Notifications & devices]\n      summary: Unregister a push token (URL-encode it). Call on sign-out.\n      parameters: [{ name: token, in: path, required: true, schema: { type: string } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /ai/assistant:\n    post:\n      tags: [AI]\n      summary: Streaming customer assistant (AI SDK UI message stream)\n      description: |\n        Same handler as `/api/ai/assistant`. Use `useChat` with `DefaultChatTransport({ api, headers: { Authorization }, body: { requestId?, policyId?, threadId? } })`.\n        The response is a Server-Sent Events UI message stream (`x-vercel-ai-ui-message-stream: v1`), not an ApiResult.\n        Response header `x-thread-id` identifies the stored conversation; pass it back as `threadId`.\n        Tools are read-only (policies, request status, quote comparison, glossary, needs assessment, draft message to broker — never sends).\n        Rate limit: 15 burst, ~6/min. 503 `unavailable` when the `ai_assistant` flag is off.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/AssistantRequest\" } } }\n      responses:\n        \"200\": { description: UI message stream, content: { text/event-stream: { schema: { type: string } } } }\n        \"503\": { $ref: \"#/components/responses/Error\" }\n\n  /partner/requests:\n    get:\n      tags: [Partner API]\n      summary: Requests routed to the broker, or submitted to the insurer (scope requests:read)\n      security: [{ apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/Limit\" }\n        - { $ref: \"#/components/parameters/Before\" }\n        - { name: status, in: query, schema: { $ref: \"#/components/schemas/RequestStatus\" } }\n        - { name: updatedSince, in: query, schema: { type: string, format: date-time } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n        \"401\": { $ref: \"#/components/responses/Error\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/quotes:\n    post:\n      tags: [Partner API]\n      summary: Post a quote for a request (scope quotes:write)\n      description: Brokers quote for appointed insurers on their routed requests; insurers quote only for themselves on requests submitted to them. A `ready_to_accept` quote moves the request to `quotes_ready` and notifies the customer.\n      security: [{ apiKey: [] }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/BrokerQuoteInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /partner/policies/{id}/issue:\n    post:\n      tags: [Partner API]\n      summary: Issue a pending policy — activates cover (insurer keys only, scope policies:issue)\n      description: Requires a confirmed payment. Records `policy_active` usage, completes the request and notifies the customer.\n      security: [{ apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/IssuePolicyBody\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n        \"409\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /partner/claims/{id}/status:\n    post:\n      tags: [Partner API]\n      summary: Update a claim's status or decision (insurer keys only, scope claims:write)\n      security: [{ apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/PartnerClaimStatusInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n\n  /partner/offers:\n    get:\n      tags: [Partner API]\n      summary: Requests offered to the broker (claim model, Addendum 2 D2/E)\n      description: |\n        Open offers by default (`status=offered`, soonest deadline first). Works with a broker member's bearer token\n        (RLS limits rows to their organisations) or a broker API key (scope `requests:read`). Each open item carries\n        `acceptUrl` (web one-tap link `/partner/offers/accept/{token}`) and `deepLink` (`covva://offers/accept/{token}`).\n        The customer's identity is only shared once the offer is accepted; `request.risk_data` is available to decide.\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/Limit\" }\n        - { $ref: \"#/components/parameters/Before\" }\n        - { name: status, in: query, schema: { type: string, enum: [offered, accepted, declined, expired, withdrawn], default: offered } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n        \"401\": { $ref: \"#/components/responses/Error\" }\n  /partner/offers/{id}:\n    post:\n      tags: [Partner API]\n      summary: Accept or decline an offered request\n      description: |\n        `accept` makes the organisation the broker of record (first to accept wins; every other open offer is withdrawn;\n        a second accept returns 422). `decline` passes the request on; when the whole round has declined it is re-offered\n        at once, otherwise when the timer expires (`routing.offer_timeout_minutes`, default 30). Callers must be an\n        adviser/supervisor/admin/owner of the offered broker (bearer) or use that broker's API key (scope `requests:read`).\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/OfferResponseInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n\n\n  # --- Broker workspace on mobile (Addendum 4 §2) — also usable by insurer users on the web client and by partner keys ---\n  /partner/dashboard:\n    get:\n      tags: [Partner API]\n      summary: Workspace dashboard — KPIs, commission summary and open work counts\n      description: |\n        Sales funnel for the range (`days` = 7, 30 or 90; per-day `series` for sparklines), renewals due in 30 days,\n        claims summary, SLA performance, lapses, the current month's commission (only for owners/admins/finance or\n        keys with `finance:read`; otherwise `commission` is null and `commissionVisible` false) and counts of open\n        offers / requests / submissions / claims. Dual-membership users pick the organisation with `orgId` (or the\n        `X-Covva-Org` header); otherwise the stored `activeWorkspace` or the only partner membership is used.\n        Insurer workspaces are refused on `X-Covva-Client: mobile` (`details.reason = insurer_web_only`).\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/OrgId\" }\n        - { name: days, in: query, schema: { type: integer, enum: [7, 30, 90], default: 30 } }\n      responses:\n        \"200\":\n          description: Dashboard\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/PartnerDashboard\" } }\n        \"401\": { $ref: \"#/components/responses/Error\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/renewals:\n    get:\n      tags: [Partner API]\n      summary: Policies due for renewal within N days (scope policies:read)\n      description: |\n        Active policies of the organisation ending within `days` (default 30, max 365), soonest first, with the\n        customer's display name, `contactAllowed` (latest data-sharing consent for your organisation type),\n        `marketingAllowed` and the renewal request if one exists. Brokers (broker of record) get full names and\n        contact details; insurer users get first name + initial and no contact details.\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/OrgId\" }\n        - { name: days, in: query, schema: { type: integer, minimum: 1, maximum: 365, default: 30 } }\n      responses:\n        \"200\":\n          description: Renewals\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties:\n                      data:\n                        type: object\n                        properties:\n                          windowDays: { type: integer }\n                          count: { type: integer }\n                          items: { type: array, items: { $ref: \"#/components/schemas/RenewalItem\" } }\n                          note: { type: string }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/commission:\n    get:\n      tags: [Partner API]\n      summary: Commission summary for a month (owners/admins/finance; scope finance:read)\n      description: Earned (brokers) or payable (insurers) from the ledger, `paid` from statements marked paid, `outstanding` = earned − paid. Period defaults to the current month.\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/OrgId\" }\n        - { name: period, in: query, schema: { type: string, pattern: \"^\\\\d{4}-(0[1-9]|1[0-2])$\", example: \"2026-10\" } }\n      responses:\n        \"200\":\n          description: Commission\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/CommissionSummary\" } }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/statements:\n    get:\n      tags: [Partner API]\n      summary: Settlement statements, newest period first (owners/admins/finance; scope finance:read)\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/OrgId\" }\n        - { name: limit, in: query, schema: { type: integer, minimum: 1, maximum: 60, default: 24 } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/statements/{id}:\n    get:\n      tags: [Partner API]\n      summary: One statement with its ledger lines and a 10-minute PDF link when rendered\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { $ref: \"#/components/parameters/OrgId\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /partner/claims:\n    get:\n      tags: [Partner API]\n      summary: Claims the organisation assists (brokers) or decides (insurers) (scope claims:read)\n      description: Newest first. `view=open` (default) hides decided/closed claims; `status` filters one status. Each item carries `statusLabel` and `customerName` (initials only for insurers).\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/OrgId\" }\n        - { name: view, in: query, schema: { type: string, enum: [open, decided, all], default: open } }\n        - { name: status, in: query, schema: { type: string, enum: [draft, reported, delivered_to_insurer, acknowledged, under_assessment, info_requested, approved, partially_approved, rejected, paid, closed, withdrawn] } }\n        - { name: policyId, in: query, schema: { type: string, format: uuid } }\n        - { name: customerId, in: query, schema: { type: string, format: uuid } }\n        - { $ref: \"#/components/parameters/Limit\" }\n        - { $ref: \"#/components/parameters/Before\" }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/claims/{id}/updates:\n    post:\n      tags: [Partner API]\n      summary: Broker records a claim step or a note from the app\n      description: |\n        Same rules as the web claims desk: a broker (owner/admin/supervisor/adviser) may mark a claim\n        `delivered_to_insurer` and, only while the insurer hasn't acted on it, `acknowledged` / `under_assessment` /\n        `info_requested`; otherwise send a note only. Decisions are insurer-only (`POST /partner/claims/{id}/status`).\n        Notifies the customer (push) when the status changes or the note is visible to them.\n      security: [{ bearerAuth: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { $ref: \"#/components/parameters/OrgId\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/PartnerClaimUpdateInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /partner/customers:\n    get:\n      tags: [Partner API]\n      summary: The broker's clients (brokers only; scope requests:read)\n      description: Active `customer_broker_assignments` plus customers whose requests or policies name the organisation as broker of record. Insurer workspaces get `403 forbidden`.\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/OrgId\" }\n        - { name: q, in: query, description: Name, email, phone or business name contains, schema: { type: string, maxLength: 100 } }\n        - { name: limit, in: query, schema: { type: integer, minimum: 1, maximum: 100, default: 50 } }\n        - { name: offset, in: query, schema: { type: integer, minimum: 0, default: 0 } }\n      responses:\n        \"200\":\n          description: Clients\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties:\n                      data:\n                        type: object\n                        properties:\n                          items: { type: array, items: { $ref: \"#/components/schemas/ClientSummary\" } }\n                          total: { type: integer }\n                          limit: { type: integer }\n                          offset: { type: integer }\n                          nextOffset: { type: [integer, \"null\"] }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/customers/{id}:\n    get:\n      tags: [Partner API]\n      summary: One client with policies, requests, claims and assignment history (brokers only)\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { $ref: \"#/components/parameters/OrgId\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /partner/documents:\n    post:\n      tags: [Partner API]\n      summary: Upload a document from the phone camera in one call\n      description: |\n        Policy schedules, certificates, IDs and claim evidence for a request, policy or claim the organisation\n        services. Send JSON with base64 `content` (plain or `data:` URL) or `multipart/form-data` with a `file`\n        part and the same field names. Max 20 MB; PDF, JPEG, PNG, WebP, HEIC or Word. Creates the `documents` row,\n        a `document_uploaded` request event, and tells the customer when a policy document is added to their wallet.\n        The two-step flow (`/documents/upload-url` → `/documents`) is still available for large files.\n      security: [{ bearerAuth: [] }]\n      parameters: [{ $ref: \"#/components/parameters/OrgId\" }]\n      requestBody:\n        required: true\n        content:\n          application/json: { schema: { $ref: \"#/components/schemas/PartnerDocumentUploadInput\" } }\n          multipart/form-data:\n            schema:\n              type: object\n              required: [file]\n              properties:\n                file: { type: string, format: binary }\n                fileName: { type: string }\n                mimeType: { type: string }\n                kind: { $ref: \"#/components/schemas/DocumentKind\" }\n                requestId: { type: string, format: uuid }\n                policyId: { type: string, format: uuid }\n                claimId: { type: string, format: uuid }\n                taskId: { type: string, format: uuid }\n                deliveredToInsurer: { type: boolean }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/messages:\n    get:\n      tags: [Partner API]\n      summary: A request thread as the servicing organisation (oldest first, with internal notes)\n      description: Marks the customer's messages as read by the broker. Customers use `GET /requests/{id}/messages`.\n      security: [{ bearerAuth: [] }]\n      parameters:\n        - { name: request_id, in: query, required: true, schema: { type: string, format: uuid } }\n        - { $ref: \"#/components/parameters/OrgId\" }\n        - { name: limit, in: query, schema: { type: integer, minimum: 1, maximum: 100, default: 50 } }\n        - { $ref: \"#/components/parameters/Before\" }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n    post:\n      tags: [Partner API]\n      summary: Message the customer on a request (push + in-app + email), or add an internal note\n      security: [{ bearerAuth: [] }]\n      parameters: [{ $ref: \"#/components/parameters/OrgId\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/PartnerMessageInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /partner/profile:\n    get:\n      tags: [Partner API]\n      summary: Organisation profile, the caller's role and insurer/broker links (appointments)\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/OrgId\" }]\n      responses:\n        \"200\":\n          description: Profile\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/PartnerProfile\" } }\n    patch:\n      tags: [Partner API]\n      summary: Update contact details (owners and admins)\n      description: Only `contactEmail`, `contactPhone`, `website`, `address`, `region` and `description`. Licence and legal details change through registration or Covva admin.\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/OrgId\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/UpdatePartnerProfileInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n\n  /verify:\n    get:\n      tags: [Verification]\n      summary: Public policy check (QR code or insurer + policy number)\n      description: |\n        Unauthenticated and rate-limited (30 per IP, refilling slowly). Pass `code` (the 10-character\n        verification code from a wallet QR / `verifyUrl`) **or** `insurer` (organisation slug) + `policyNumber`.\n        Returns only non-personal fields: valid, status, insurerName, categoryName, coverStart, coverEnd and\n        policyNumberMasked (last 4). A \"not found\" result is not proof that a risk is uninsured — the policy may\n        have been bought outside Covva.\n      security: []\n      parameters:\n        - { name: code, in: query, schema: { type: string, pattern: \"^[0-9A-HJKMNP-TV-Z]{10}$\" } }\n        - { name: insurer, in: query, description: Insurer organisation slug, schema: { type: string } }\n        - { name: policyNumber, in: query, schema: { type: string, minLength: 3 } }\n      responses:\n        \"200\":\n          description: Verification result\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties:\n                      data:\n                        type: object\n                        required: [valid]\n                        properties:\n                          valid: { type: boolean }\n                          status: { type: string, description: \"active | outside cover dates | pending issuance | cancelled | expired | …\" }\n                          insurerName: { type: string }\n                          categoryName: { type: string }\n                          coverStart: { type: [string, \"null\"], format: date }\n                          coverEnd: { type: [string, \"null\"], format: date }\n                          policyNumberMasked: { type: [string, \"null\"], description: \"Last 4 characters visible\" }\n                          message: { type: string }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n        \"429\": { $ref: \"#/components/responses/Error\" }\n  /openapi:\n    get:\n      tags: [System]\n      summary: This document (YAML)\n      security: []\n      responses:\n        \"200\": { description: OpenAPI document, content: { application/yaml: { schema: { type: string } } } }\n\nwebhooks:\n  request.created:\n    post:\n      tags: [Webhooks]\n      summary: A request was routed to the broker of record\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  request.status_changed:\n    post:\n      tags: [Webhooks]\n      summary: A request changed status (data.from_status, data.status)\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  quote.ready:\n    post:\n      tags: [Webhooks]\n      summary: Quotes were sent to the customer, or a binding quote was posted\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  application.submitted:\n    post:\n      tags: [Webhooks]\n      summary: The customer applied for a quote\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  payment.succeeded:\n    post:\n      tags: [Webhooks]\n      summary: Premium confirmed by the payment provider (policy pending issuance — not active)\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  policy.issued:\n    post:\n      tags: [Webhooks]\n      summary: The insurer issued the policy; cover is active\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  claim.reported:\n    post:\n      tags: [Webhooks]\n      summary: A claim was reported (reporting is not approval)\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  claim.status_changed:\n    post:\n      tags: [Webhooks]\n      summary: A claim changed status\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  complaint.filed:\n    post:\n      tags: [Webhooks]\n      summary: A complaint owned by your organisation was filed\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  test.ping:\n    post:\n      tags: [Webhooks]\n      summary: Test delivery sent from the settings page\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n\ncomponents:\n  securitySchemes:\n    bearerAuth:\n      type: http\n      scheme: bearer\n      bearerFormat: Supabase access token (JWT)\n    apiKey:\n      type: apiKey\n      in: header\n      name: x-api-key\n      description: \"Partner key `imk_<prefix>_<secret>`; the platform stores only sha256(key).\"\n\n  parameters:\n    CovvaClient:\n      name: X-Covva-Client\n      in: header\n      required: false\n      description: Which client is calling. Missing = `web`. Insurer and staff accounts are refused on `mobile`.\n      schema: { type: string, enum: [mobile, web, partner-web], default: web }\n    Id: { name: id, in: path, required: true, schema: { type: string, format: uuid } }\n    Limit: { name: limit, in: query, schema: { type: integer, minimum: 1, maximum: 100, default: 25 } }\n    Before: { name: before, in: query, description: Cursor (ISO timestamp from `nextCursor`), schema: { type: string, format: date-time } }\n    OrgId: { name: orgId, in: query, required: false, description: \"Organisation to act for when the user belongs to several (also accepted as the `X-Covva-Org` header). Defaults to the stored active workspace or the only partner membership.\", schema: { type: string, format: uuid } }\n\n  responses:\n    Ok:\n      description: Success\n      content: { application/json: { schema: { $ref: \"#/components/schemas/OkEnvelope\" } } }\n    Page:\n      description: A page of items\n      content:\n        application/json:\n          schema:\n            allOf:\n              - $ref: \"#/components/schemas/OkEnvelope\"\n              - properties:\n                  data:\n                    type: object\n                    properties:\n                      items: { type: array, items: { type: object } }\n                      nextCursor: { type: [string, \"null\"], format: date-time }\n    Error:\n      description: Error\n      content: { application/json: { schema: { $ref: \"#/components/schemas/ErrorEnvelope\" } } }\n    Me:\n      description: Current user\n      content:\n        application/json:\n          schema:\n            allOf:\n              - $ref: \"#/components/schemas/OkEnvelope\"\n              - properties:\n                  data:\n                    type: object\n                    properties:\n                      profile: { type: object, description: \"profiles row; Ghana Card returned as ghana_card_last4 only\" }\n                      memberships: { type: array, items: { type: object } }\n                      isPartner: { type: boolean }\n                      workspaces: { type: array, items: { $ref: \"#/components/schemas/Workspace\" }, description: \"Customer workspace first, then one per broker/insurer membership\" }\n                      activeWorkspace: { $ref: \"#/components/schemas/ActiveWorkspace\" }\n                      client: { type: string, enum: [mobile, web, partner-web], description: \"Echo of X-Covva-Client\" }\n                      flags: { type: object, additionalProperties: { type: boolean }, description: \"feature_flags (e.g. demo_mode, ai_assistant)\" }\n                      consents: { type: object, additionalProperties: { type: object } }\n                      versions: { type: object, properties: { terms: { type: [string, \"null\"] }, privacy: { type: [string, \"null\"] } } }\n                      needsConsent: { type: boolean }\n\n  schemas:\n    Workspace:\n      type: object\n      required: [type, mobileAllowed, allowed]\n      properties:\n        type: { type: string, enum: [customer, broker, insurer] }\n        orgId: { type: string, format: uuid }\n        orgName: { type: string }\n        role: { type: string, description: \"member_role (owner, admin, supervisor, adviser, underwriter, claims_officer, finance, viewer)\" }\n        mobileAllowed: { type: boolean, description: \"Usable from the mobile app (false for insurer workspaces)\" }\n        allowed: { type: boolean, description: \"Usable from the calling client\" }\n    ActiveWorkspace:\n      type: object\n      required: [type]\n      properties:\n        type: { type: string, enum: [customer, broker, insurer] }\n        orgId: { type: string, format: uuid }\n    SetActiveWorkspaceInput:\n      type: object\n      required: [type]\n      properties:\n        type: { type: string, enum: [customer, broker, insurer] }\n        orgId: { type: string, format: uuid, description: \"Required unless type is customer\" }\n    OkEnvelope:\n      type: object\n      required: [ok, data]\n      properties:\n        ok: { const: true }\n        data: {}\n    ErrorEnvelope:\n      type: object\n      required: [ok, error]\n      properties:\n        ok: { const: false }\n        error:\n          type: object\n          required: [code, message]\n          properties:\n            code: { $ref: \"#/components/schemas/ErrorCode\" }\n            message: { type: string, description: Safe to show to users }\n            details: {}\n    ErrorCode:\n      type: string\n      enum: [unauthorised, forbidden, not_found, invalid_input, business_rule, conflict, rate_limited, unavailable, internal_error]\n\n    RequestStatus:\n      type: string\n      enum: [draft, submitted, awaiting_customer_info, adviser_action, insurer_response, quotes_ready, payment_confirmation, policy_documents, completed, cancelled, closed_no_cover]\n    QuoteStatus:\n      type: string\n      enum: [estimate, awaiting_underwriting, ready_to_accept, accepted, expired, declined, withdrawn]\n    PolicyStatus:\n      type: string\n      enum: [pending_issuance, active, lapsed, cancelled, expired, renewed]\n    ClaimStatus:\n      type: string\n      enum: [draft, reported, delivered_to_insurer, acknowledged, under_assessment, info_requested, approved, partially_approved, rejected, paid, closed, withdrawn]\n    ComplaintStatus:\n      type: string\n      enum: [open, acknowledged, investigating, resolved, escalated_nic, closed]\n    PaymentStatus:\n      type: string\n      enum: [pending, processing, succeeded, failed, refunded, reversed, abandoned]\n    CategoryAvailability:\n      type: string\n      enum: [integrated, broker_assisted, planned]\n    DocumentKind:\n      type: string\n      enum: [id_document, vehicle_registration, drivers_licence, photo, proof_of_address, medical, policy_schedule, certificate, policy_wording, receipt, endorsement, claim_evidence, police_report, invoice, other]\n    ConsentType:\n      type: string\n      enum: [terms, privacy, marketing, data_sharing_broker, data_sharing_insurer, ai_assistance]\n\n    RiskField:\n      type: object\n      required: [key, label, type]\n      properties:\n        key: { type: string }\n        label: { type: string }\n        type: { type: string, enum: [text, number, currency, select, multiselect, boolean, date, region] }\n        required: { type: boolean }\n        min: { type: number }\n        max: { type: number }\n        placeholder: { type: string }\n        help: { type: string }\n        options: { type: array, items: { type: object, properties: { value: { type: string }, label: { type: string } } } }\n    Category:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        slug: { type: string }\n        name: { type: string }\n        short_description: { type: [string, \"null\"] }\n        icon: { type: [string, \"null\"], description: lucide icon name }\n        segment: { type: string, enum: [personal, business, specialist] }\n        availability: { $ref: \"#/components/schemas/CategoryAvailability\" }\n        availabilityLabel: { type: string }\n        availabilityPromise: { type: string }\n        risk_schema: { type: array, items: { $ref: \"#/components/schemas/RiskField\" } }\n        required_documents: { type: array, items: { $ref: \"#/components/schemas/DocumentKind\" } }\n        regulatory_note: { type: [string, \"null\"] }\n        default_sla_hours: { type: integer }\n\n    UpdateProfileInput:\n      type: object\n      properties:\n        fullName: { type: string, maxLength: 200 }\n        preferredName: { type: [string, \"null\"] }\n        phone: { type: [string, \"null\"], pattern: \"^\\\\+?\\\\d{9,15}$\" }\n        accountType: { type: string, enum: [individual, business] }\n        businessName: { type: [string, \"null\"] }\n        dateOfBirth: { type: [string, \"null\"], format: date }\n        ghanaCardNumber: { type: [string, \"null\"], pattern: \"^GHA-\\\\d{9}-\\\\d$\" }\n        region: { type: [string, \"null\"] }\n        city: { type: [string, \"null\"] }\n        locale: { type: string }\n        avatarUrl: { type: [string, \"null\"], format: uri }\n        notificationPrefs: { type: object, properties: { email: { type: boolean }, sms: { type: boolean }, push: { type: boolean }, whatsapp: { type: boolean } } }\n        onboarded: { const: true }\n    RecordConsentsInput:\n      type: object\n      required: [consents]\n      properties:\n        consents:\n          type: array\n          minItems: 1\n          maxItems: 10\n          items:\n            type: object\n            required: [type, granted]\n            properties:\n              type: { $ref: \"#/components/schemas/ConsentType\" }\n              granted: { type: boolean }\n              version: { type: string }\n              context: { type: string }\n    NeedsAssessmentInput:\n      type: object\n      required: [answers]\n      properties:\n        answers: { type: object, additionalProperties: { oneOf: [{ type: string }, { type: array, items: { type: string } }, { type: boolean }] } }\n        anonymousId: { type: string }\n    NeedsResult:\n      type: object\n      properties:\n        id: { type: [string, \"null\"], format: uuid }\n        suggestions:\n          type: array\n          items:\n            type: object\n            properties:\n              slug: { type: string }\n              name: { type: string }\n              priority: { type: string, enum: [essential, recommended, consider] }\n              why: { type: string }\n              availability: { $ref: \"#/components/schemas/CategoryAvailability\" }\n        needsAdviser: { type: boolean }\n        adviserReason: { type: [string, \"null\"] }\n        note: { type: string }\n\n    CreateRequestInput:\n      type: object\n      required: [categorySlug, risk]\n      properties:\n        categorySlug: { type: string }\n        type: { type: string, enum: [new_cover, renewal, switch, endorsement, service], default: new_cover }\n        risk: { type: object, additionalProperties: true, description: \"Answers keyed by the category's risk_schema field keys\" }\n        relatedPolicyId: { type: string, format: uuid }\n        needsAssessmentId: { type: string, format: uuid }\n        submit: { type: boolean, default: true }\n        talkToExpert: { type: boolean, default: false, description: \"Ask for advice: always routed to a broker, whatever the insurer's integration level\" }\n    DisclosureAckInput:\n      type: object\n      properties:\n        stage: { type: string, enum: [before_advice, before_application, broker_change], default: before_application }\n        method: { type: string, enum: [in_app, sms, email, call], default: in_app }\n    PostMessageInput:\n      type: object\n      required: [body]\n      properties:\n        body: { type: string, minLength: 1, maxLength: 4000 }\n        attachments: { type: array, items: { type: object, required: [documentId, name], properties: { documentId: { type: string, format: uuid }, name: { type: string } } } }\n    CompleteTaskInput:\n      type: object\n      properties:\n        documentId: { type: string, format: uuid }\n        note: { type: string, maxLength: 1000 }\n\n    Quote:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        status: { $ref: \"#/components/schemas/QuoteStatus\" }\n        statusLabel: { type: string }\n        statusHint: { type: [string, \"null\"] }\n        is_binding: { type: boolean }\n        premium: { type: number }\n        taxes: { type: number }\n        fees: { type: number }\n        currency: { type: string, example: GHS }\n        billing_period: { type: string }\n        sum_insured: { type: [number, \"null\"] }\n        excess: { type: [number, \"null\"] }\n        coverage: { type: array, items: { type: object, properties: { key: { type: string }, label: { type: string }, included: { type: boolean } } } }\n        limits: { type: object }\n        excesses: { type: object }\n        exclusions: { type: array, items: { type: string } }\n        key_exclusion: { type: [string, \"null\"] }\n        waiting_period_days: { type: integer }\n        optional_benefits: { type: array, items: { type: object, properties: { key: { type: string }, label: { type: string }, premium: { type: number } } } }\n        valid_until: { type: [string, \"null\"], format: date-time }\n        expired: { type: boolean }\n        paid_placement: { type: boolean }\n        commission_disclosure: { type: [string, \"null\"] }\n        labels: { type: array, items: { type: string }, description: \"Explained labels, e.g. Lowest premium\" }\n        demo: { type: boolean }\n        insurer: { type: object, properties: { id: { type: string }, name: { type: string }, slug: { type: string }, logo_url: { type: [string, \"null\"] } } }\n        product: { type: [object, \"null\"], properties: { id: { type: string }, name: { type: string }, tier: { type: [string, \"null\"] } } }\n    QuotesResult:\n      type: object\n      properties:\n        request: { type: object }\n        broker: { type: [object, \"null\"] }\n        quotes: { type: array, items: { $ref: \"#/components/schemas/Quote\" } }\n        comparison:\n          type: object\n          properties:\n            engineVersion: { type: string }\n            insurersCompared: { type: integer }\n            productsCompared: { type: integer }\n            criteria: { type: object }\n            ranked: { type: array, items: { type: object } }\n            paidPlacements: { type: array, items: { type: object } }\n            materialExclusions: { type: array, items: { type: object } }\n            disclaimer: { type: string }\n        summary: { type: string }\n        disclosure: { type: [string, \"null\"] }\n        comparedAt: { type: string, format: date-time }\n        demoMode: { type: boolean }\n        demoDisclaimer: { type: [string, \"null\"] }\n\n    UploadUrlInput:\n      type: object\n      required: [scope, fileName, mimeType, sizeBytes]\n      properties:\n        scope: { type: string, enum: [requests, policies, claims, profile] }\n        fileName: { type: string, maxLength: 200 }\n        mimeType: { type: string, enum: [application/pdf, image/jpeg, image/png, image/webp, image/heic, application/msword, application/vnd.openxmlformats-officedocument.wordprocessingml.document] }\n        sizeBytes: { type: integer, maximum: 20971520 }\n        kind: { $ref: \"#/components/schemas/DocumentKind\" }\n        requestId: { type: string, format: uuid }\n        policyId: { type: string, format: uuid }\n        claimId: { type: string, format: uuid }\n        taskId: { type: string, format: uuid }\n    ConfirmUploadInput:\n      allOf:\n        - $ref: \"#/components/schemas/UploadUrlInput\"\n        - type: object\n          required: [path]\n          properties:\n            path: { type: string }\n            checksum: { type: string }\n\n    ApplyInput:\n      type: object\n      required: [quoteId, declarations, acceptTerms]\n      properties:\n        quoteId: { type: string, format: uuid }\n        declarations: { type: object, additionalProperties: { oneOf: [{ type: boolean }, { type: string }] } }\n        selectedBenefits: { type: array, items: { type: string }, description: optional_benefits keys }\n        acceptTerms: { const: true }\n    InitPaymentRequest:\n      type: object\n      required: [applicationId]\n      properties:\n        applicationId: { type: string, format: uuid }\n        channel: { type: string, enum: [mobile_money, card, bank_transfer], default: mobile_money }\n        callbackUrl: { type: string, format: uri }\n        momo:\n          type: object\n          required: [phone, provider]\n          properties:\n            phone: { type: string, example: \"0244123456\" }\n            provider: { type: string, enum: [mtn, vod, atl] }\n    InitiatePaymentResult:\n      type: object\n      properties:\n        paymentId: { type: string, format: uuid }\n        reference: { type: string }\n        authorizationUrl: { type: [string, \"null\"], format: uri }\n        status: { $ref: \"#/components/schemas/PaymentStatus\" }\n        displayText: { type: [string, \"null\"] }\n        provider: { type: string, enum: [paystack, hubtel, simulator, bank_transfer] }\n        bankTransfer:\n          oneOf:\n            - { type: \"null\" }\n            - $ref: \"#/components/schemas/BankTransferInstructions\"\n    BankTransferInstructions:\n      type: object\n      required: [bank, accountName, accountNumber, reference, kind, amount, currency, instructions]\n      properties:\n        bank: { type: string }\n        accountName: { type: string }\n        accountNumber: { type: string }\n        reference: { type: string, description: Quote this on the transfer; it is matched at reconciliation }\n        kind: { type: string, enum: [insurer_account, paystack_dva], description: insurer's own account, or a Paystack dedicated virtual account unique to the customer (auto-confirms) }\n        amount: { type: number }\n        currency: { type: string, example: GHS }\n        instructions: { type: string, description: Plain-language instructions to show the customer }\n    VehicleLookupInput:\n      type: object\n      required: [registration]\n      properties:\n        registration: { type: string, example: \"GR 1234-23\" }\n    VehicleLookupResult:\n      type: object\n      required: [registration, found]\n      properties:\n        registration: { type: string, description: Normalised plate }\n        found: { type: boolean }\n        source: { type: [string, \"null\"], enum: [dvla, manual, cache, null] }\n        data:\n          type: [object, \"null\"]\n          properties:\n            make: { type: string }\n            model: { type: string }\n            year: { type: integer }\n            body: { type: string }\n            colour: { type: string }\n            chassis_last4: { type: string }\n            engine_cc: { type: integer }\n            seats: { type: integer }\n            use: { type: string, enum: [private, commercial] }\n        fetchedAt: { type: string, format: date-time }\n    ShareQuotesInput:\n      type: object\n      properties:\n        channel: { type: string, enum: [link, whatsapp, email], default: link }\n        email: { type: string, format: email, description: Recipient for `email` (defaults to the account email) }\n    ShareResult:\n      type: object\n      required: [id, token, url, channel, expiresAt, text, whatsappUrl]\n      properties:\n        id: { type: string, format: uuid }\n        token: { type: string }\n        url: { type: string, format: uri, description: Public read-only comparison page }\n        channel: { type: string, enum: [link, whatsapp, email] }\n        expiresAt: { type: string, format: date-time }\n        text: { type: string, description: Plain-text summary (WhatsApp / SMS friendly) }\n        whatsappUrl: { type: string, format: uri }\n        emailSent: { type: boolean }\n\n    WebhookEnvelope:\n      type: object\n      required: [id, event, created_at, attempt, org_id, data]\n      properties:\n        id: { type: string, description: Delivery id (stable across retries — de-duplicate on it) }\n        event: { type: string, enum: [request.created, request.status_changed, quote.ready, application.submitted, payment.succeeded, policy.issued, claim.reported, claim.status_changed, complaint.filed, test.ping] }\n        created_at: { type: string, format: date-time }\n        attempt: { type: integer, minimum: 1, maximum: 5 }\n        org_id: { type: string, format: uuid, description: The organisation the endpoint belongs to }\n        data:\n          type: object\n          additionalProperties: true\n          description: Ids, references, statuses, amounts and dates only. Never personal data.\n          properties:\n            request_id: { type: string, format: uuid }\n            reference: { type: string }\n            status: { type: string }\n            from_status: { type: string }\n            policy_id: { type: string, format: uuid }\n            claim_id: { type: string, format: uuid }\n            complaint_id: { type: string, format: uuid }\n            payment_id: { type: string, format: uuid }\n            application_id: { type: string, format: uuid }\n            quote_id: { type: string, format: uuid }\n    AddExternalPolicyInput:\n      type: object\n      required: [categorySlug, policyNumber, coverStart, coverEnd]\n      description: Give either `insurerOrgId` (an insurer on the platform) or `insurerName` (any other insurer; stored as `external_insurer_name`, no organisation is created).\n      properties:\n        categorySlug: { type: string }\n        insurerOrgId: { type: string, format: uuid, description: From GET /catalog/insurers }\n        insurerName: { type: string, minLength: 2, maxLength: 120, description: Insurer not on the platform, as printed on the policy }\n        policyNumber: { type: string }\n        coverStart: { type: string, format: date }\n        coverEnd: { type: string, format: date }\n        premium: { type: number }\n        sumInsured: { type: number }\n        nickname: { type: string, maxLength: 60 }\n        documentId: { type: string, format: uuid }\n    RenewalInput:\n      type: object\n      properties:\n        risk: { type: object, additionalProperties: true, description: Defaults to the original request's risk details }\n        changes: { type: string, maxLength: 2000, description: \"What has changed (posted to the broker)\" }\n\n    ReportClaimInput:\n      type: object\n      required: [policyId, incidentType, incidentAt, description]\n      properties:\n        policyId: { type: string, format: uuid }\n        incidentType: { type: string, example: Accident }\n        incidentAt: { type: string, format: date-time }\n        location: { type: string, maxLength: 300 }\n        description: { type: string, minLength: 10, maxLength: 5000 }\n        amountClaimed: { type: number }\n    FileComplaintInput:\n      type: object\n      required: [subject, description, category]\n      properties:\n        subject: { type: string, minLength: 3, maxLength: 200 }\n        description: { type: string, minLength: 10, maxLength: 5000 }\n        category: { type: string, enum: [advice, service, claims, payment, data_privacy, technology, other] }\n        againstParty: { type: string, enum: [broker, insurer, platform], default: broker }\n        requestId: { type: string, format: uuid }\n        policyId: { type: string, format: uuid }\n        claimId: { type: string, format: uuid }\n        desiredOutcome: { type: string, maxLength: 2000 }\n    RegisterDeviceInput:\n      type: object\n      required: [token, platform]\n      properties:\n        token: { type: string, example: \"ExponentPushToken[xxxxxxxxxxxxxxxxxxxxxx]\" }\n        platform: { type: string, enum: [ios, android, web] }\n        provider: { type: string, enum: [expo, fcm, apns, webpush], default: expo }\n        appVersion: { type: string }\n    AssistantRequest:\n      type: object\n      required: [messages]\n      properties:\n        messages: { type: array, maxItems: 60, items: { type: object, description: \"AI SDK UIMessage { id, role, parts }\" } }\n        requestId: { type: string, format: uuid }\n        policyId: { type: string, format: uuid }\n        threadId: { type: string, format: uuid }\n\n    BrokerQuoteInput:\n      type: object\n      required: [requestId, insurerOrgId, status, premium]\n      properties:\n        requestId: { type: string, format: uuid }\n        insurerOrgId: { type: string, format: uuid }\n        productVersionId: { type: string, format: uuid }\n        status: { type: string, enum: [estimate, awaiting_underwriting, ready_to_accept] }\n        premium: { type: number, minimum: 0 }\n        excess: { type: number, minimum: 0 }\n        sumInsured: { type: number, minimum: 0 }\n        keyExclusion: { type: string }\n        validUntil: { type: string, format: date-time, description: Defaults to 14 days for ready_to_accept }\n        brokerNote: { type: string, maxLength: 2000 }\n    IssuePolicyBody:\n      type: object\n      required: [policyNumber, coverStart, coverEnd]\n      properties:\n        policyNumber: { type: string, minLength: 3, maxLength: 60 }\n        coverStart: { type: string, format: date }\n        coverEnd: { type: string, format: date }\n    PartnerClaimStatusInput:\n      type: object\n      required: [status]\n      properties:\n        status: { type: string, enum: [acknowledged, under_assessment, info_requested, approved, partially_approved, rejected, paid, closed] }\n        note: { type: string, maxLength: 2000 }\n        insurerReference: { type: string }\n        decisionAmount: { type: number, minimum: 0 }\n        visibleToCustomer: { type: boolean, default: true }\n    OfferResponseInput:\n      type: object\n      required: [action]\n      properties:\n        action: { type: string, enum: [accept, decline] }\n        reason: { type: string, maxLength: 500, description: Optional decline reason (kept for routing analytics) }\n    Offer:\n      type: object\n      description: A request offered to a broker (`GET /partner/offers` item).\n      properties:\n        id: { type: string, format: uuid }\n        request_id: { type: string, format: uuid }\n        status: { type: string, enum: [offered, accepted, declined, expired, withdrawn] }\n        round: { type: integer, description: Offer round (1 = first batch of brokers) }\n        offered_at: { type: string, format: date-time }\n        responds_by: { type: string, format: date-time, description: Accept before this or the request moves on }\n        acceptUrl: { type: [string, \"null\"], description: One-tap accept link (web) }\n        deepLink: { type: [string, \"null\"], description: \"covva://offers/accept/{token}\" }\n        request: { type: object, description: \"id, reference, title, type, status, risk_data, talk_to_expert, complexity_flags, category\" }\n\n    # --- Broker workspace on mobile (Addendum 4 §2) ---\n    DocumentKind:\n      type: string\n      enum: [id_document, vehicle_registration, drivers_licence, photo, proof_of_address, medical, policy_schedule, certificate, policy_wording, receipt, endorsement, claim_evidence, police_report, invoice, other]\n    SalesDay:\n      type: object\n      description: One day of the sales funnel (from `partner_sales_summary`).\n      properties:\n        day: { type: string, format: date }\n        requests: { type: integer }\n        quotes: { type: integer }\n        conversions: { type: integer, description: Applications accepted }\n        policies_issued: { type: integer }\n        premium: { type: number }\n        platform_fee: { type: number }\n        broker_commission: { type: number }\n    PartnerDashboard:\n      type: object\n      properties:\n        org: { type: object, properties: { id: { type: string, format: uuid }, name: { type: string }, type: { type: string, enum: [broker, insurer] }, role: { type: [string, \"null\"] } } }\n        range: { type: object, properties: { days: { type: integer }, from: { type: string, format: date }, to: { type: string, format: date } } }\n        kpis:\n          type: object\n          properties:\n            requests: { type: integer }\n            quotes: { type: integer }\n            conversions: { type: integer }\n            policiesIssued: { type: integer }\n            premium: { type: number }\n            platformFee: { type: number }\n            brokerCommission: { type: number }\n            conversionRate: { type: [number, \"null\"], description: Conversions as % of quotes }\n            change: { type: object, additionalProperties: { type: [number, \"null\"] }, description: \"% change vs the previous period per KPI\" }\n        series: { type: array, items: { $ref: \"#/components/schemas/SalesDay\" } }\n        open: { type: object, properties: { offers: { type: integer }, requests: { type: integer }, submissions: { type: integer }, claims: { type: integer } } }\n        renewals: { type: object, properties: { count: { type: integer }, windowDays: { type: integer }, next: { type: array, items: { type: object }, description: \"First 10 rows of partner_renewals (snake_case)\" } } }\n        claims:\n          type: object\n          properties:\n            byStatus: { type: object, additionalProperties: { type: integer } }\n            total: { type: integer }\n            open: { type: integer }\n            decided: { type: integer }\n            avgDaysToDecision: { type: [number, \"null\"] }\n            staleOpen: { type: integer, description: Open for more than 14 days }\n            openSlaBreaches: { type: [integer, \"null\"], description: Null until SLA timers exist }\n        sla:\n          type: object\n          properties:\n            requests_measured: { type: integer }\n            requests_on_time: { type: integer }\n            requests_breached: { type: integer }\n            requests_open_overdue: { type: integer }\n            submissions_measured: { type: integer }\n            submissions_on_time: { type: integer }\n            submissions_late: { type: integer }\n            submissions_open_overdue: { type: integer }\n            on_time_rate: { type: [number, \"null\"], description: Percentage }\n        lapses:\n          type: object\n          properties: { lapsed: { type: integer }, cancelled: { type: integer }, expired: { type: integer }, renewed: { type: integer }, active: { type: integer }, ended: { type: integer }, lapse_rate: { type: [number, \"null\"] } }\n        commission: { oneOf: [{ $ref: \"#/components/schemas/CommissionRow\" }, { type: \"null\" }] }\n        commissionVisible: { type: boolean }\n        period: { type: string, example: \"2026-10\" }\n    CommissionRow:\n      type: object\n      description: Raw row of `partner_commission_summary` (snake_case).\n      properties:\n        period: { type: string }\n        period_start: { type: string, format: date }\n        period_end: { type: string, format: date }\n        currency: { type: string }\n        earned: { type: number }\n        paid: { type: number }\n        outstanding: { type: number }\n        revenue_share: { type: number }\n        platform_fee: { type: number }\n        entries: { type: integer }\n        statement_id: { type: [string, \"null\"], format: uuid }\n        statement_status: { type: [string, \"null\"], enum: [draft, issued, paid, null] }\n        statement_net_due: { type: [number, \"null\"] }\n    CommissionSummary:\n      type: object\n      properties:\n        period: { type: string, example: \"2026-10\" }\n        periodStart: { type: string, format: date }\n        periodEnd: { type: string, format: date }\n        currency: { type: string }\n        earned: { type: number, description: Brokers — commission credited; insurers — commission payable }\n        paid: { type: number }\n        outstanding: { type: number }\n        revenueShare: { type: number }\n        platformFee: { type: number }\n        entries: { type: integer }\n        statement: { type: [object, \"null\"], properties: { id: { type: string, format: uuid }, status: { type: string }, netDue: { type: number } } }\n        side: { type: string, enum: [earned, payable] }\n        note: { type: string }\n    RenewalItem:\n      type: object\n      properties:\n        policyId: { type: string, format: uuid }\n        reference: { type: string }\n        policyNumber: { type: [string, \"null\"] }\n        category: { type: object, properties: { id: { type: string, format: uuid }, name: { type: string } } }\n        coverEnd: { type: string, format: date }\n        daysLeft: { type: integer }\n        premium: { type: [number, \"null\"] }\n        currency: { type: string }\n        status: { type: string }\n        customer:\n          type: object\n          properties:\n            id: { type: string, format: uuid }\n            name: { type: string, description: Full name for brokers; first name + initial for insurers }\n            email: { type: [string, \"null\"], description: Brokers only }\n            phone: { type: [string, \"null\"], description: Brokers only }\n        contactAllowed: { type: boolean, description: Latest data-sharing consent for your organisation type }\n        marketingAllowed: { type: boolean }\n        renewalRequest: { type: [object, \"null\"], properties: { id: { type: string, format: uuid }, status: { type: string } } }\n        remindersSent: { type: integer }\n    PartnerClaimUpdateInput:\n      type: object\n      description: Give a status, a note, or both.\n      properties:\n        status: { type: string, enum: [delivered_to_insurer, acknowledged, under_assessment, info_requested] }\n        note: { type: string, maxLength: 2000 }\n        visibleToCustomer: { type: boolean, default: true }\n    ClientSummary:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        name: { type: string }\n        email: { type: [string, \"null\"] }\n        phone: { type: [string, \"null\"] }\n        accountType: { type: string, enum: [individual, business] }\n        businessName: { type: [string, \"null\"] }\n        kycStatus: { type: string, enum: [unverified, pending, verified, rejected] }\n        region: { type: [string, \"null\"] }\n        city: { type: [string, \"null\"] }\n        source: { type: string, enum: [assignment, request, policy], description: How the client is linked to the broker }\n        assignedSince: { type: [string, \"null\"], format: date-time }\n        openRequests: { type: integer }\n        activePolicies: { type: integer }\n        lastRequestAt: { type: [string, \"null\"], format: date-time }\n    PartnerDocumentUploadInput:\n      type: object\n      required: [fileName, mimeType, content]\n      properties:\n        fileName: { type: string, maxLength: 200 }\n        mimeType: { type: string, enum: [application/pdf, image/jpeg, image/png, image/webp, image/heic, application/msword, application/vnd.openxmlformats-officedocument.wordprocessingml.document] }\n        kind: { $ref: \"#/components/schemas/DocumentKind\" }\n        content: { type: string, description: \"Base64 file contents (plain or data: URL), max 20 MB decoded\" }\n        requestId: { type: string, format: uuid }\n        policyId: { type: string, format: uuid }\n        claimId: { type: string, format: uuid }\n        taskId: { type: string, format: uuid }\n        deliveredToInsurer: { type: boolean, default: false }\n    PartnerMessageInput:\n      type: object\n      required: [requestId, body]\n      properties:\n        requestId: { type: string, format: uuid }\n        body: { type: string, minLength: 1, maxLength: 4000 }\n        attachments: { type: array, maxItems: 10, items: { type: object, properties: { documentId: { type: string, format: uuid }, name: { type: string } } } }\n        internal: { type: boolean, default: false, description: Team-only note, never shown to the customer }\n    PartnerProfile:\n      type: object\n      properties:\n        organisation: { type: object, description: \"organizations row: name, slug, type, status, logo_url, contact_email, contact_phone, website, address, region, NIC licence fields, integration_level\" }\n        membership: { type: [object, \"null\"], properties: { role: { type: string }, roleLabel: { type: string }, isSupervisor: { type: boolean }, canEditProfile: { type: boolean } } }\n        teamSize: { type: integer }\n        links:\n          type: object\n          description: Insurer appointments (brokers see insurers; insurers see brokers)\n          properties:\n            kind: { type: string, enum: [insurers, brokers] }\n            active: { type: integer }\n            items: { type: array, items: { type: object, properties: { id: { type: string, format: uuid }, active: { type: boolean }, organisation: { type: object }, category: { type: [object, \"null\"] }, agreementReference: { type: [string, \"null\"] }, startsOn: { type: [string, \"null\"] }, endsOn: { type: [string, \"null\"] } } } }\n        workspaces: { type: array, items: { type: object, properties: { orgId: { type: string, format: uuid }, orgName: { type: string }, type: { type: string }, role: { type: string } } } }\n    UpdatePartnerProfileInput:\n      type: object\n      minProperties: 1\n      properties:\n        contactEmail: { type: [string, \"null\"], format: email }\n        contactPhone: { type: [string, \"null\"] }\n        website: { type: [string, \"null\"], format: uri }\n        address: { type: [string, \"null\"], maxLength: 400 }\n        region: { type: [string, \"null\"], maxLength: 100 }\n        description: { type: [string, \"null\"], maxLength: 2000 }\n";
